async function trialMemberFixture(respond:Parameters<typeof environment>[0],readOnly=false,launcher?:(env:Awaited<ReturnType<typeof environment>>)=>MemberLauncher){
 const env=await environment(respond),oldWorker=process.env.FRIEND_PI_MEMBER_WORKER;process.env.FRIEND_PI_MEMBER_WORKER=env.worker;
 const ctx:PluginContext={origin:'user',dataDir:join(env.root,'data'),agentDir:env.agentDir,projectDir:env.project,projectId:'native-trial',sessionId:'host',runId:'parent-run',modelId:'swarm-fixture/fixture',thinkingLevel:'off',isIdle:()=>true,history:()=>[],readSource:()=>{throw Error('no model supplied source');},complete:async()=>{throw Error('unused');},request:async()=>undefined,emit:()=>{},notify:()=>{},appendEntry:()=>{},policy:{v:1,revision:1,stage:'main',unsettledTools:0,canSwitchRole:false,tools:['read','grep','find','ls','write','edit','bash','friend_expert'],writeScopes:['.'],executionMode:'swarm',planMode:false}};
 const expert=new ExpertController(ctx.dataDir),services=new RuntimeCapabilityServices(ctx.dataDir),ledger=new TaskLedger(ctx.dataDir),checkStore=new RecordStore('checks',ctx.dataDir),controller=new SwarmController(launcher?.(env)),observations:Record<string,unknown>[]=[];
 ctx.readCheck=ref=>new SourcePolicy(checkStore).readCheck(ref,ctx.projectId);
 ctx.request=async(plugin,action,input)=>{if(plugin==='runtime')return action==='task.identity'?ledger.resolveIdentity(input||{},ctx):action==='task.repair.claimBatch'?ledger.claimRepairBatch(input||{},ctx):services.dispatch(action,input||{},{...ctx,origin:'plugin'});if(plugin==='memory')throw Error('optional plugin absent');assert.equal(plugin,'expert');return expert.dispatch(action,input||{},{...ctx,origin:'plugin'});};
 ctx.requestWithContext=async(plugin,action,input,trusted)=>{assert.equal(plugin,'expert');if(action==='trial.observe')observations.push(input);return expert.dispatch(action,input,{...ctx,...trusted,origin:'plugin'});};
 const id='seed.implementer.1',created=await expert.dispatch('candidate.submit',{id,key:'trial-method',skillBody:{title:'Native checked method',applicability:'implementation',body:'Run the requested objective check and report its actual result.',restrictions:{tools:readOnly?['read']:['read','write','edit','bash'],writeScopes:readOnly?[]:['.']}},evidence:[]},ctx) as {version:number;revision:number};
 await expert.dispatch('trial.configure',{id,expectedRevision:created.revision,scope:{projectId:ctx.projectId,applicability:'implementation'},limits:{maxTasks:3},key:'trial'},ctx);
 assert.equal(created.version,2);assert.equal(expert.skillCatalog.head(id,ctx).stable?.version,1);assert.equal(expert.freeze({expertId:'implementer'},ctx).experts[0].frozenSkills!.find(skill=>skill.id===id)!.version,1,'an unselected candidate cannot replace the stable default');
 let graphSequence=0;const create=async(tasks=1,roleId?:string,expertId:string|undefined='implementer')=>{await expert.dispatch('select',expertId==='implementer'?{ids:['implementer'],skillRefs:[{id,version:created.version}]}:{ids:[]},ctx);return controller.dispatch('create',{goal:'Bound trial outcomes to actual native member checks',deferPreparation:true,maxWorkers:1,tasks:Array.from({length:tasks},(_,i)=>({id:`task-${i}`,title:`implementation ${i}`,expertId:expertId||undefined,roleId,prompt:`NATIVE_TRIAL_GRAPH_${++graphSequence}_TASK_${i}: execute the supplied Bash check and report.`,mode:'write',dependencies:i?[`task-${i-1}`]:[],writeScopes:['.']})),contract:{artifacts:[{id:'answer',kind:'answer',target:'answer',required:true}],checks:[]}},ctx) as Promise<Graph>;};
 const snapshot=()=> (controller.snapshot(ctx) as {graphs:Graph[]}).graphs;
 return {env,ctx,expert,controller,id,version:created.version,observations,create,snapshot,head:()=>expert.skillCatalog.head(id,ctx),close:async()=>{await controller.dispose();expert.dispose();services.dispose();ledger.dispose();checkStore.close();if(oldWorker===undefined)delete process.env.FRIEND_PI_MEMBER_WORKER;else process.env.FRIEND_PI_MEMBER_WORKER=oldWorker;await env.cleanup();}};
}
function currentTrialTools(input:ModelRequest):unknown[]{const messages=input.messages as {role:string;content?:unknown}[];return messages.slice(messages.findLastIndex(m=>m.role==='user'&&/NATIVE_TRIAL|RETRY_FAIL/.test(JSON.stringify(m.content)))+1).filter(m=>m.role==='tool');}

for(const exitCode of [0,7])test(`production Pi member trial registers native Bash exit ${exitCode} and settles only after actual completion`,{timeout:90000},async()=>{
 let entered=false,release!:()=>void;const gate=new Promise<void>(done=>{release=done;});
 const f=await trialMemberFixture(async input=>{if(currentTrialTools(input).length===0)return {tool:'bash',args:{command:`printf 'native-objective\n'; exit ${exitCode}`}};entered=true;await gate;return 'Objective check finished; report the actual outcome.';});
 try{
  const graph=await f.create();await f.controller.dispatch('start',{graphId:graph.id},f.ctx);await waitFor(()=>entered&&f.snapshot()[0].attempts[0].nativeChecks?.length===1);
  let attempt=f.snapshot()[0].attempts[0];assert.equal(f.head().trial!.completedTasks,0,'a single successful tool event is not a completed member task');assert.equal(f.observations.length,0);assert.equal(attempt.status,'running');
  release();await waitFor(()=>f.snapshot()[0].status==='completed');attempt=f.snapshot()[0].attempts[0];assert.equal(attempt.exitReceipt?.status,'terminated');assert.equal(attempt.trialObservation?.status,'observed',attempt.trialObservation?.error);assert.equal(f.head().trial!.completedTasks,1);assert.equal(Boolean(f.head().trial!.frozen),exitCode!==0);assert.equal(f.observations.length,1);
  const ref=attempt.nativeChecks![0],check=f.ctx.readCheck!(ref) as {passed:boolean;output:{exitCode:number;trialAttribution:{v:number;decisionEntryId:string;adoptions:{operationId:string;journalEntryId:string;skillsHash:string}[]}};sources:{entryId:string;hash:string}[]};assert.equal(ref.producerRunId,attempt.id);assert.equal(ref.taskId,attempt.taskId);assert.equal(check.passed,exitCode===0);assert.equal(check.output.exitCode,exitCode);
  const native=readFileSync(attempt.sessionFile!,'utf8').trim().split('\n').map(line=>JSON.parse(line)),raw=native.find(e=>e.id===check.sources[0].entryId);assert.equal(raw.message.toolName,'bash');assert.equal(ref.hash,digest(raw.message));assert.equal(check.sources[0].hash,digest(visibleText(raw.message.content)));assert.ok(native.some(e=>e.customType===nativeCheckType));const attribution=check.output.trialAttribution,decisionIndex=native.findIndex(e=>e.id===attribution.decisionEntryId);assert.equal(attribution.v,1);assert.ok(decisionIndex>=0&&decisionIndex<native.indexOf(raw));assert.equal(native[decisionIndex].message.role,'assistant');assert.ok(native[decisionIndex].message.content.some((p:{type:string;id?:string;name?:string})=>p.type==='toolCall'&&p.id===raw.message.toolCallId&&p.name==='bash'));assert.ok(attribution.adoptions.length);for(const bound of attribution.adoptions){const canonicalIndex=native.findIndex(e=>e.id===bound.journalEntryId);assert.ok(canonicalIndex>=0&&canonicalIndex<decisionIndex);assert.equal(native[canonicalIndex].data.operationId,bound.operationId);assert.equal(digest(native[canonicalIndex].data.skills),bound.skillsHash);}
  const branch=native.slice(1),current=f.snapshot()[0];assert.equal(readMemberChecks(branch,current,attempt,attempt.sessionId!).length,1);
  for(const tamper of ['exit','tool','adoption','input','attempt'] as const){const changed=structuredClone(branch),receipt=changed.find(e=>e.customType===nativeCheckType);if(tamper==='exit')receipt.data.exitCode=exitCode===0?3:0;if(tamper==='tool')changed.find(e=>e.id===receipt.data.toolEntryId).message.content=[{type:'text',text:'changed'}];if(tamper==='adoption')receipt.data.adoptions[0].skillsHash=digest('changed');if(tamper==='input')changed.find(e=>e.type==='message'&&e.message.role==='user').message.content='different input';const owner=tamper==='attempt'?{...attempt,id:'old-attempt'}:attempt;if(tamper==='attempt')assert.deepEqual(readMemberChecks(changed,current,owner,attempt.sessionId!),[]);else assert.throws(()=>readMemberChecks(changed,current,owner,attempt.sessionId!),/未核验/);}
 }finally{release();await f.close();}
});

