test('native member trial quota isolates same-named tasks across graphs and denies the fourth before inference',{timeout:240000},async()=>{
 const f=await trialMemberFixture(input=>currentTrialTools(input).length>0?'Successful native check.':{tool:'bash',args:{command:'exit 0'}});
 try{for(let i=0;i<3;i++){const graph=await f.create();await f.controller.dispatch('start',{graphId:graph.id},f.ctx);await waitFor(()=>['completed','paused','failed','stopped'].includes(f.snapshot().find(g=>g.id===graph.id)!.status)).catch(error=>{throw new Error(`trial graph ${i+1} did not settle: ${String(error)}; ${JSON.stringify(f.snapshot().find(g=>g.id===graph.id))}`);});const terminal=f.snapshot().find(g=>g.id===graph.id)!;assert.equal(terminal.status,'completed',`trial graph ${i+1}: ${JSON.stringify({status:terminal.status,error:terminal.error,pauseReason:terminal.pauseReason,attempts:terminal.attempts.map(a=>({status:a.status,error:a.error,trial:a.trialObservation}))})}`);}assert.equal(f.head().trial!.reservedTasks,3,JSON.stringify(f.snapshot().map(g=>({id:g.id,attempts:g.attempts.map(a=>({id:a.id,status:a.status,adopt:a.expertAdoptions,trial:a.trialObservation,checks:a.nativeChecks}))}))));assert.equal(f.head().trial!.completedTasks,3);const before=f.env.requests(),fourth=await f.create();await f.controller.dispatch('start',{graphId:fourth.id},f.ctx);await waitFor(()=>['completed','paused','failed','stopped'].includes(f.snapshot().find(g=>g.id===fourth.id)!.status));const last=f.snapshot().find(g=>g.id===fourth.id)!;assert.equal(last.status,'paused',JSON.stringify({status:last.status,error:last.error,attempts:last.attempts.map(a=>({status:a.status,error:a.error}))}));assert.equal(f.env.requests(),before,'trial reservation is denied before calling a provider');assert.match(last.error||'',/3|额度|试用/);assert.equal(f.head().trial!.reservedTasks,3);assert.equal(f.head().trial!.completedTasks,3);assert.equal(last.attempts[0].nativeChecks,undefined);assert.ok(f.snapshot().every(g=>g.tasks[0].id==='task-0'));assert.equal(new Set(f.snapshot().map(g=>g.attempts[0].startPromptDigest)).size,4);}finally{await f.close();}
});

test('native retry keeps one graph-task quota but the new failed attempt freezes its exact version',{timeout:150000},async()=>{
 const f=await trialMemberFixture(input=>{const messages=input.messages as {role:string;content?:unknown}[],retry=JSON.stringify(messages).includes('RETRY_FAIL');return currentTrialTools(input).length>0?'Actual retry check finished.':{tool:'bash',args:{command:retry?'exit 6':'exit 0'}};});
 try{const graph=await f.create();await f.controller.dispatch('start',{graphId:graph.id},f.ctx);await waitFor(()=>f.snapshot()[0].status==='completed',60000);const original=f.snapshot()[0].attempts[0];await f.controller.dispatch('pause',{graphId:graph.id},f.ctx);await f.controller.dispatch('rework',{graphId:graph.id,taskIds:['task-0'],reason:'Test a new actual failed execution',prompts:{'task-0':'RETRY_FAIL: run objective Bash exit 6 and report.'}},f.ctx);await waitFor(()=>['completed','paused'].includes(f.snapshot()[0].status)&&f.snapshot()[0].attempts.length===2,60000).catch(error=>{throw Error(String(error)+JSON.stringify({status:f.snapshot()[0].status,tasks:f.snapshot()[0].tasks,attempts:f.snapshot()[0].attempts.map(a=>({id:a.id,status:a.status,error:a.error,trial:a.trialObservation})),teammates:(f.controller.snapshot(f.ctx) as {teammates:unknown[]}).teammates}));});const final=f.snapshot()[0],retry=final.attempts[1];assert.equal(final.status,'completed',final.error);assert.equal(retry.trialObservation?.status,'observed',retry.trialObservation?.error);assert.equal(f.head().trial!.reservedTasks,1);assert.equal(f.head().trial!.completedTasks,1);assert.equal(f.head().trial!.frozen,true);assert.notEqual(original.id,retry.id);assert.equal(original.nativeChecks![0].producerRunId,original.id);assert.equal(retry.nativeChecks![0].producerRunId,retry.id);assert.notEqual(original.nativeChecks![0].checkId,retry.nativeChecks![0].checkId);assert.equal(f.observations.length,2);const oldReceipt=readFileSync(original.sessionFile!,'utf8').trim().split('\n').map(line=>JSON.parse(line)).find(e=>e.customType===nativeCheckType&&e.data.runId===original.id);await (f.controller as unknown as {memberOutput(id:string,attemptId:string,message:MemberOutput,ctx:PluginContext):Promise<void>}).memberOutput(graph.id,original.id,{v:2,protocol:2,type:'native.check',memberId:original.memberId,generation:original.generation,attemptId:original.id,entryId:oldReceipt.id,operationId:oldReceipt.data.operationId},f.ctx);assert.equal(f.snapshot()[0].tasks[0].currentAttempt,retry.id);assert.equal(f.snapshot()[0].attempts[1].nativeChecks![0].producerRunId,retry.id);assert.equal(f.observations.length,2,'late prior-generation receipt must not trigger another observation');}finally{await f.close();}
});

test('native old-version completion cannot credit or freeze a replacement trial version',{timeout:90000},async()=>{
 let entered=false,release!:()=>void;const gate=new Promise<void>(done=>{release=done;});const f=await trialMemberFixture(async input=>{if(currentTrialTools(input).length===0)return {tool:'bash',args:{command:'exit 5'}};entered=true;await gate;return 'Late original method result.';});
 try{const graph=await f.create();await f.controller.dispatch('start',{graphId:graph.id},f.ctx);await waitFor(()=>entered&&f.snapshot()[0].attempts[0].nativeChecks?.length===1);const changed=await f.expert.dispatch('skill.update',{id:f.id,expectedRevision:f.head().revision,body:'A replacement method version awaiting its own actual checks.',key:'replacement'},f.ctx) as {version:number;revision:number};await f.expert.dispatch('trial.configure',{id:f.id,expectedRevision:changed.revision,scope:{projectId:f.ctx.projectId,applicability:'implementation'},limits:{maxTasks:3},key:'replacement-trial'},f.ctx);assert.equal(changed.version,f.version+1);release();await waitFor(()=>['completed','paused'].includes(f.snapshot()[0].status));assert.equal(f.head().version,changed.version);assert.equal(f.head().trial!.reservedTasks,0);assert.equal(f.head().trial!.completedTasks,0);assert.equal(Boolean(f.head().trial!.frozen),false);assert.equal(f.snapshot()[0].attempts[0].trialObservation?.status,'waiting');assert.ok(f.observations.every(o=>o.runId===f.snapshot()[0].attempts[0].id));}finally{release();await f.close();}
});

test('production Pi member interrupted Bash without structured exit retains waiting evidence',{timeout:90000},async()=>{
 const f=await trialMemberFixture(()=>({tool:'bash',args:{command:'printf started > native-started.txt; sleep 4'}}));
 try{const graph=await f.create();await f.controller.dispatch('start',{graphId:graph.id},f.ctx);await waitFor(()=>{const attempt=f.snapshot()[0].attempts[0];return !!attempt&&existsSync(join(attempt.cwd,'native-started.txt'));});assert.equal(f.head().trial!.reservedTasks,1);assert.equal(f.snapshot()[0].attempts[0].nativeChecks,undefined);await f.controller.dispatch('stop',{graphId:graph.id},f.ctx);const attempt=f.snapshot()[0].attempts[0];assert.equal(attempt.trialObservation?.status,'waiting');assert.equal(attempt.trialObservation?.outcome,'cancelled');assert.equal(f.head().trial!.completedTasks,0);assert.equal(Boolean(f.head().trial!.frozen),false);const native=readFileSync(attempt.sessionFile!,'utf8');assert.equal(native.includes(nativeCheckType),false,'abort without structured exit cannot synthesize a failed check');assert.equal(f.observations.some(o=>o.outcome==='completed'||o.outcome==='failed'),false);}finally{await f.close();}
});

test('a reliably terminated member with invalid delivery still freezes its actual failed trial check',{timeout:90000},async()=>{
 const f=await trialMemberFixture(input=>currentTrialTools(input).length>0?'Invalid role delivery prose.':{tool:'bash',args:{command:'exit 4'}});
 try{const graph=await f.create(1,'implementer');await f.controller.dispatch('start',{graphId:graph.id},f.ctx);await waitFor(()=>f.snapshot()[0].status==='paused'&&!!f.snapshot()[0].attempts[0].trialObservation);const attempt=f.snapshot()[0].attempts[0];assert.equal(attempt.exitReceipt?.status,'terminated');assert.equal(attempt.trialObservation?.status,'observed',attempt.trialObservation?.error);assert.equal(attempt.trialObservation?.outcome,'failed');assert.equal(f.head().trial!.completedTasks,1);assert.equal(f.head().trial!.frozen,true);assert.equal(attempt.nativeChecks?.length,1);}finally{await f.close();}
});

for(const alwaysTimeout of [false,true])test(`native trial observation response timeout ${alwaysTimeout?'stops after three attempts':'retries the same key after teammate release'}`,{timeout:90000},async()=>{
 const f=await trialMemberFixture(input=>currentTrialTools(input).length>0?'Native success.':{tool:'bash',args:{command:'exit 0'}}),original=f.ctx.requestWithContext!;let responses=0;
 f.ctx.requestWithContext=async(...args)=>{const result=await original(...args);if(args[1]==='trial.observe'&&(++responses===1||alwaysTimeout))throw Error('fixture response timeout after canonical settlement');return result;};
 try{const graph=await f.create();await f.controller.dispatch('start',{graphId:graph.id},f.ctx);await waitFor(()=>f.snapshot()[0].status==='completed');await waitFor(()=>alwaysTimeout?f.snapshot()[0].attempts[0].trialObservation?.attempts===3:f.snapshot()[0].attempts[0].trialObservation?.status==='observed');const attempt=f.snapshot()[0].attempts[0];assert.equal(responses,alwaysTimeout?3:2);assert.equal(attempt.trialObservation?.attempts,responses);assert.equal(attempt.trialObservation?.status,alwaysTimeout?'waiting':'observed');assert.equal(f.head().trial!.completedTasks,1,'a lost response cannot double-credit an idempotent canonical result');assert.equal(new Set(f.observations.map(o=>o.key)).size,1);assert.equal(attempt.trialObservation?.retryAt,undefined);await new Promise(done=>setTimeout(done,300));assert.equal(responses,alwaysTimeout?3:2);}finally{await f.close();}
});

test('native trial response retry recovers from durable waiting after its original controller closes',{timeout:90000},async()=>{
 const f=await trialMemberFixture(input=>currentTrialTools(input).length>0?'Native success.':{tool:'bash',args:{command:'exit 0'}}),original=f.ctx.requestWithContext!;let responses=0,recovered:SwarmController|undefined;
 f.ctx.requestWithContext=async(...args)=>{const result=await original(...args);if(args[1]==='trial.observe'&&++responses===1)throw Error('fixture lost response before controller shutdown');return result;};
 try{const graph=await f.create();await f.controller.dispatch('start',{graphId:graph.id},f.ctx);await waitFor(()=>f.snapshot()[0].status==='completed');assert.equal(f.snapshot()[0].attempts[0].trialObservation?.status,'waiting');await f.controller.dispose();recovered=new SwarmController();await waitFor(()=>((recovered!.snapshot(f.ctx) as {graphs:Graph[]}).graphs[0].attempts[0].trialObservation?.status==='observed'));assert.equal(responses,2);assert.equal(f.head().trial!.completedTasks,1);assert.equal(new Set(f.observations.map(o=>o.key)).size,1);}finally{await recovered?.dispose();await f.close();}
});

for(const cancelled of [false,true])test(`late actual native close ${cancelled?'preserves cancellation without credit':'settles original failed intent after unknown stop receipt'}`,{timeout:90000},async()=>{
 let actual:StopObject|undefined,release!:()=>void;const gate=new Promise<void>(done=>{release=done;});let finalReached=false,finishModel!:()=>void;const modelGate=new Promise<void>(done=>{finishModel=done;});
 const f=await trialMemberFixture(async input=>{if(!currentTrialTools(input).length)return {tool:'bash',args:{command:'exit 3'}};finalReached=true;if(cancelled)await modelGate;return 'Invalid role delivery prose.';},false,env=>(start,output,exited)=>{
  const child=fork(env.worker,[],{cwd:start.cwd,detached:process.platform!=='win32',stdio:['ignore','pipe','pipe','ipc'],execArgv:[],env:{...process.env,FRIEND_PI_DATA_DIR:start.dataDir,FRIEND_PI_AGENT_DIR:start.agentDir}});child.stdout?.resume();child.stderr?.resume();const owned=ownChild(child,start.attemptId,'member',process.platform!=='win32',()=>{},1000);
  child.on('message',(message:MemberOutput)=>output(message));child.on('close',code=>exited(code));child.send(start);
  return {pid:child.pid,groupOwned:process.platform!=='win32',send:message=>{if(child.connected)child.send(message);},closed:owned.ended.then(async receipt=>{actual=receipt;await gate;return receipt;}),stop:async()=>{void owned.stop(()=>{if(child.connected)child.send({v:1,type:'stop'});});return {id:start.attemptId,kind:'member',status:'unknown',detail:'fixture delays delivery of the actual host close receipt'};}};
 });
 const original=f.ctx.requestWithContext!;let lostUnknown=0;f.ctx.requestWithContext=async(...args)=>{const result=await original(...args);if(args[1]==='trial.observe'&&args[2].outcome==='unknown'&&++lostUnknown===1)throw Error('fixture lost unknown response before late close');return result;};
 try{const graph=await f.create(1,'implementer');await f.controller.dispatch('start',{graphId:graph.id},f.ctx);await waitFor(()=>finalReached&&f.snapshot()[0].attempts[0].nativeChecks?.length===1);if(cancelled)await f.controller.dispatch('stop',{graphId:graph.id},f.ctx);await waitFor(()=>!!actual&&f.snapshot()[0].attempts[0].trialObservation?.status==='waiting');assert.equal(f.head().trial!.completedTasks,0);assert.equal(Boolean(f.head().trial!.frozen),false);release();await waitFor(()=>cancelled?f.snapshot()[0].attempts[0].exitReceipt?.status==='terminated':f.snapshot()[0].attempts[0].trialObservation?.status==='observed');const attempt=f.snapshot()[0].attempts[0];assert.equal(attempt.trialTerminalOutcome,cancelled?'cancelled':'failed');assert.equal(attempt.trialObservation?.outcome,cancelled?'cancelled':'failed');assert.equal(f.head().trial!.completedTasks,cancelled?0:1);assert.equal(Boolean(f.head().trial!.frozen),!cancelled);await new Promise(done=>setTimeout(done,400));assert.equal(f.snapshot()[0].attempts[0].trialObservation?.status,cancelled?'waiting':'observed','an older unknown retry cannot overwrite the late reliable failed observation');assert.equal(f.observations.filter(o=>o.outcome==='failed').length,cancelled?0:1);}finally{finishModel();release();await f.close();}
});

test('native parallel Bash and later canonical trial adoption keep the entire group waiting',{timeout:90000},async()=>{
 let turns=0,firstExpertId='',laterExpertId='';const f=await trialMemberFixture(()=>{turns++;if(turns===1)return {tool:'friend_expert',args:{action:'use',input:{id:firstExpertId}}};if(turns===2)return {tools:[{tool:'bash',args:{command:'sleep 0.25; exit 7'}},{tool:'friend_expert',args:{action:'use',input:{id:laterExpertId}}}]};return 'Report the native failure without crediting a method adopted in the same tool batch.';});
 try{const createMethod=async(title:string,prompt:string)=>{const method=await f.expert.dispatch('create',{title,prompt,tools:['read','write','edit','bash'],skills:[]},f.ctx) as {id:string};const id=`legacy.${method.id}`,head=f.expert.skillCatalog.head(id,f.ctx);await f.expert.dispatch('trial.configure',{id,expectedRevision:head.revision,scope:{projectId:f.ctx.projectId,applicability:f.ctx.projectId},limits:{maxTasks:3},key:`trial-${method.id}`},f.ctx);assert.equal(f.expert.skillCatalog.head(id,f.ctx).stable,undefined);return {expertId:method.id,skillId:id};};const first=await createMethod('First method','Run the requested objective check and report its actual result.'),later=await createMethod('Later method','Verify only checks produced after this method was adopted.');firstExpertId=first.expertId;laterExpertId=later.expertId;const graph=await f.create(1,undefined,'');await f.controller.dispatch('start',{graphId:graph.id},f.ctx);await waitFor(()=>['completed','paused'].includes(f.snapshot()[0].status));const final=f.snapshot()[0],attempt=final.attempts[0];assert.equal(final.status,'completed',final.error);assert.equal(attempt.expertAdoptions?.length,2);assert.equal(attempt.trialObservation?.status,'waiting');assert.match(attempt.trialObservation?.error||'',/早于后续采用/);for(const method of [first,later]){const head=f.expert.skillCatalog.head(method.skillId,f.ctx);assert.equal(head.trial!.reservedTasks,1);assert.equal(head.trial!.completedTasks,0);assert.equal(Boolean(head.trial!.frozen),false);}for(const adoption of attempt.expertAdoptions as {skills:{id:string;version:number;statusAtFreeze:string}[]}[])assert.ok(adoption.skills.some(skill=>[first.skillId,later.skillId].includes(skill.id)&&skill.version===1&&skill.statusAtFreeze==='trial'));assert.equal(f.observations.length,0);const raw=readFileSync(attempt.sessionFile!,'utf8').trim().split('\n').map(line=>JSON.parse(line)),receipt=raw.find(e=>e.customType===nativeCheckType),callIndex=raw.findIndex(e=>e.type==='message'&&e.message.role==='assistant'&&e.message.content.some((p:{type:string;name?:string})=>p.type==='toolCall'&&p.name==='bash')),late=raw.findIndex(e=>e.customType==='friend-pi.expert.adoption'&&e.data.id===laterExpertId);assert.ok(callIndex<late);assert.equal(receipt.data.adoptions.length,1);assert.throws(()=>readMemberChecks(raw.slice(1),final,attempt,attempt.sessionId!,true),/早于后续采用/);const forged=structuredClone(raw.slice(1)),lateAdoption=(attempt.expertAdoptions as {operationId:string;journalEntryId:string;skills:unknown}[])[1];forged.find(e=>e.customType===nativeCheckType).data.adoptions.push({operationId:lateAdoption.operationId,journalEntryId:lateAdoption.journalEntryId,skillsHash:digest(lateAdoption.skills)});assert.throws(()=>readMemberChecks(forged,final,attempt,attempt.sessionId!,true),/未核验/);}finally{await f.close();}
});

for(const {workTools,mode,toolsMode} of [{workTools:[],mode:'read',toolsMode:'allowlist'},{workTools:['read'],mode:'read',toolsMode:'allowlist'},{workTools:['read'],mode:'read',toolsMode:'inherit'},{workTools:['grep','find','ls'],mode:'write',toolsMode:'allowlist'}] as const)test(`native resolved Expert first request freezes prompt, Skill, model and ${mode}/${toolsMode}/${workTools.join(',')||'empty'} work tools`,async()=>{
 let observed:Record<string,unknown>|undefined;
 const env=await environment(input=>{observed=input;assert.equal(input.model,'spawn-model');const payload=JSON.stringify(input.messages);assert.match(payload,/EXACT_SPAWN_PROMPT/);assert.match(payload,/EXACT_SELECTED_SKILL_BODY/);const names=((input.tools||[]) as {function:{name:string}}[]).map(t=>t.function.name);for(const tool of ['read','write','edit','bash','grep','find','ls'])assert.equal(names.includes(tool),(workTools as readonly string[]).includes(tool));if(toolsMode==='allowlist')assert.deepEqual([...names].sort(),[...workTools].sort(),'explicit allowlist is the exact model-visible set, including coordination');return 'Frozen spawn observed';});
 const models=JSON.parse(readFileSync(join(env.agentDir,'models.json'),'utf8'));models.providers['swarm-fixture'].models.push({...models.providers['swarm-fixture'].models[0],id:'spawn-model'});writeFileSync(join(env.agentDir,'models.json'),JSON.stringify(models));
 const spawn={v:1,id:'custom-user-expert',title:'Custom',version:7,hash:'exact-spawn-hash',prompt:'EXACT_SPAWN_PROMPT',skills:[{id:'selected',version:4,hash:'skill-hash',body:'EXACT_SELECTED_SKILL_BODY'}],toolsMode,tools:workTools,modelId:'swarm-fixture/spawn-model',thinkingLevel:'off'};
 const start:MemberStart={v:1,type:'start',graphId:'spawn-fixture',taskId:'a',attemptId:randomUUID(),cwd:env.project,dataDir:join(env.root,'data'),agentDir:env.agentDir,sessionDir:join(env.root,'sessions'),modelId:spawn.modelId,thinkingLevel:'off',prompt:'Use selected frozen expertise.',mode,writeScopes:mode==='write'?['.']:[],parentTools:['read','grep','find','ls'],expert:{spawn}};
 const child=fork(env.worker,[],{cwd:env.project,stdio:['ignore','pipe','pipe','ipc'],execArgv:[]});child.stdout?.resume();child.stderr?.resume();let timer:ReturnType<typeof setTimeout>|undefined,validations=0;
 try{const terminal=new Promise<Extract<MemberOutput,{type:'settled'}>>((done,reject)=>{timer=setTimeout(()=>reject(Error('spawn native timeout')),15000);child.on('message',(message:MemberOutput)=>{if(message.type==='request'&&message.action==='expert.validate'){assert.equal(message.input.hash,spawn.hash);validations++;child.send({v:1,type:'request.response',requestId:message.requestId,result:{valid:true}});}if(message.type==='settled'){clearTimeout(timer);done(message);}if(message.type==='failed'){clearTimeout(timer);reject(Error(message.error));}});child.once('error',reject);});child.send(start);const result=await terminal;assert.ok(observed);assert.ok(validations>0);const entries=readFileSync(result.sessionFile!,'utf8').trim().split('\n').map(line=>JSON.parse(line));const evidence=entries.find(e=>e.type==='custom'&&e.customType==='friend-pi.expert.spawn');assert.deepEqual(evidence.data.snapshot,spawn);assert.deepEqual([...evidence.data.effectiveTools].sort(),((observed!.tools||[]) as {function:{name:string}}[]).map(t=>t.function.name).sort());assert.equal(evidence.data.modelId,spawn.modelId);assert.ok(entries.some(e=>e.type==='message'&&e.message.role==='user'&&JSON.stringify(e.message.content).includes('EXACT_SELECTED_SKILL_BODY')));await new Promise<void>(done=>{if(child.exitCode!==null)done();else child.once('exit',()=>done());});}finally{clearTimeout(timer);child.kill('SIGTERM');await env.cleanup();}
});

for(const scenario of ['parent-only-allowlist','parent-only-inherit','known-mode-restriction'] as const)test(`native child validates actual tool definitions before inference: ${scenario}`,async()=>{
 const explicit=scenario!=='parent-only-inherit',missing=scenario==='parent-only-allowlist',requested=scenario==='known-mode-restriction'?['read','write']:['read','read_document'];
 const env=await environment(input=>{const advertised=((input.tools||[]) as {function:{name:string}}[]).map(tool=>tool.function.name);assert.equal(advertised.includes('read_document'),false);assert.equal(advertised.includes('write'),false);assert.ok(advertised.includes('read'));return 'Only supported authorized child tools were advertised.';});
 const spawn={v:1,id:'parent-custom-tool-profile',title:'Parent custom tools',version:1,hash:'parent-custom-tools',prompt:'Use only available child tools.',skills:[],toolsMode:explicit?'allowlist':'inherit',tools:requested,modelId:'swarm-fixture/fixture',thinkingLevel:'off'};
 const start:MemberStart={v:1,type:'start',graphId:'actual-child-tools',taskId:'a',attemptId:randomUUID(),cwd:env.project,dataDir:join(env.root,'data'),agentDir:env.agentDir,sessionDir:join(env.root,'sessions'),modelId:spawn.modelId,thinkingLevel:'off',prompt:'Inspect the requested tool configuration.',mode:'read',writeScopes:[],parentTools:['read','write','read_document'],expert:{spawn}};
 const child=fork(env.worker,[],{cwd:env.project,stdio:['ignore','pipe','pipe','ipc'],execArgv:[]});child.stdout?.resume();child.stderr?.resume();let timer:ReturnType<typeof setTimeout>|undefined;
 try{const terminal=new Promise<Extract<MemberOutput,{type:'settled'|'failed'}>>((done,reject)=>{timer=setTimeout(()=>reject(Error('child tool definition validation timed out')),15000);child.on('message',(message:MemberOutput)=>{if(message.type==='request'&&message.action==='expert.validate')child.send({v:1,type:'request.response',requestId:message.requestId,result:{valid:true}});if(message.type==='settled'||message.type==='failed'){clearTimeout(timer);done(message);}});child.once('error',reject);});child.send(start);const result=await terminal;if(missing){assert.equal(result.type,'failed');if(result.type==='failed')assert.match(result.error,/不可用.*read_document/);assert.equal(env.requests(),0,'advertised parent-only custom tool must fail before any provider request');}else{assert.equal(result.type,'settled',result.type==='failed'?result.error:undefined);assert.ok(env.requests()>0);}
 await new Promise<void>(done=>{if(child.exitCode!==null)done();else child.once('exit',()=>done());});
 }finally{clearTimeout(timer);child.kill('SIGTERM');await env.cleanup();}
});
